-- ============================================================================
-- VIEWPORT CENTER
-- ============================================================================

local function GetViewport()
	local camera = workspace.CurrentCamera

	if camera then
		return camera.ViewportSize
	end

	return Vector2.new(1920, 1080)
end

local function GetCenterPosition()
	local viewport = GetViewport()

	return UDim2.fromOffset(
		viewport.X * 0.5,
		viewport.Y * 0.5
	)
end

-- ============================================================================
-- TOP TOGGLE POSITION
-- ============================================================================

local function GetTopTogglePosition()
	local viewport = GetViewport()

	return UDim2.fromOffset(
		viewport.X * 0.5,
		-5
	)
end

-- ============================================================================
-- MINIMIZE ANIMATION
-- ============================================================================

local function MinimizeUI()
	if IsTransitioning or IsMinimized then
		return
	end

	IsTransitioning = true
	IsMinimized = true

	MinimizeButton.Active = false
	AntiHitButton.Active = false

	local centerPosition = GetCenterPosition()

	-- STEP 1: Main UI bergerak ke tengah
	Tween(
		MainFrame,
		0.45,
		{
			Position = centerPosition
		},
		Enum.EasingStyle.Quart,
		Enum.EasingDirection.InOut
	)

	task.wait(0.47)

	-- STEP 2: Pause di tengah
	task.wait(0.30)

	-- STEP 3: Main UI mengecil menjadi bentuk toggle
	Tween(
		MainFrame,
		0.40,
		{
			Size = UDim2.fromOffset(245, 50)
		},
		Enum.EasingStyle.Quart,
		Enum.EasingDirection.InOut
	)

	task.wait(0.42)

	-- STEP 4: Hide main UI
	MainFrame.Visible = false

	-- STEP 5: Munculkan toggle tepat di tengah
	ToggleButton.Position = centerPosition
	ToggleButton.Size = UDim2.fromOffset(245, 50)
	ToggleButton.Visible = true

	-- STEP 6: Toggle bergerak ke bagian paling atas
	task.wait(0.05)

	local topPosition = GetTopTogglePosition()

	Tween(
		ToggleButton,
		0.55,
		{
			Position = topPosition
		},
		Enum.EasingStyle.Quart,
		Enum.EasingDirection.Out
	)

	task.wait(0.58)

	ToggleButton.Active = true
	IsTransitioning = false
end

-- ============================================================================
-- RESTORE ANIMATION
-- ============================================================================

local function RestoreUI()
	if IsTransitioning or not IsMinimized then
		return
	end

	IsTransitioning = true

	ToggleButton.Active = false

	local centerPosition = GetCenterPosition()

	-- STEP 1: Toggle turun ke tengah
	Tween(
		ToggleButton,
		0.55,
		{
			Position = centerPosition
		},
		Enum.EasingStyle.Quart,
		Enum.EasingDirection.InOut
	)

	task.wait(0.58)

	-- STEP 2: Pause di tengah
	task.wait(0.30)

	-- STEP 3: Hide toggle
	ToggleButton.Visible = false

	-- STEP 4: Main UI muncul dalam bentuk kecil
	MainFrame.Visible = true
	MainFrame.Position = centerPosition
	MainFrame.Size = UDim2.fromOffset(245, 50)

	-- STEP 5: Morph menjadi panel
	Tween(
		MainFrame,
		0.45,
		{
			Size = UDim2.fromOffset(MAIN_WIDTH, MAIN_HEIGHT)
		},
		Enum.EasingStyle.Back,
		Enum.EasingDirection.Out
	)

	task.wait(0.48)

	-- STEP 6: Bergerak kembali ke posisi kiri
	Tween(
		MainFrame,
		0.55,
		{
			Position = MAIN_HOME_POSITION
		},
		Enum.EasingStyle.Quart,
		Enum.EasingDirection.Out
	)

	task.wait(0.58)

	IsMinimized = false
	IsTransitioning = false

	MinimizeButton.Active = true
	AntiHitButton.Active = true
end

